def edge_score(edges: List[int]) -> int:
    n = len(edges)
    score = [0] * n
    for i, target in enumerate(edges):
        score[target] += i

    best = 0
    for node in range(1, n):
        if score[node] > score[best]:  # strict: ties keep the smaller label
            best = node
    return best

