    while queue:
        prev = None
        for _ in range(len(queue)):
            node = queue.popleft()
            v = node.val
            if level % 2 == 0:
                # odd values, strictly increasing
                if v % 2 == 0 or (prev is not None and v <= prev):
                    return False
            else:
                # even values, strictly decreasing
                if v % 2 == 1 or (prev is not None and v >= prev):
                    return False
            prev = v
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        level += 1
    return True

