        else:
            lh, lans = info[node.left]
            rh, rans = info[node.right]
            if lh > rh:
                info[node] = (lh + 1, lans)
            elif rh > lh:
                info[node] = (rh + 1, rans)
            else:
                info[node] = (lh + 1, node)     # deepest leaves on both sides meet here
    return info[root][1]

def is_path_crossing(path: str) -> bool:
    moves = {"N": (0, 1), "S": (0, -1), "E": (1, 0), "W": (-1, 0)}
    x = y = 0
    seen = {(0, 0)}
    for c in path:
        dx, dy = moves[c]
        x += dx
        y += dy
        if (x, y) in seen:
            return True
        seen.add((x, y))
    return False
